static inline void Cy_SMIF_Interrupt(SMIF_Type *base, cy_stc_smif_context_t *context)
{
    uint32_t interruptStatus = Cy_SMIF_GetInterruptStatusMasked(base);
    if (0U != (interruptStatus & 0x1UL))
    {
        Cy_SMIF_PushTxFifo(base, context);
        Cy_SMIF_ClearInterrupt(base, 0x1UL);
    }
    else if (0U != (interruptStatus & 0x2UL))
    {
        Cy_SMIF_PopRxFifo(base, context);
        Cy_SMIF_ClearInterrupt(base, 0x2UL);
    }
    else if (0U != (interruptStatus & 0x4UL))
    {
        context->transferStatus = CY_SMIF_XIP_ERROR;
        Cy_SMIF_ClearInterrupt(base, 0x4UL);
    }
    else if (0U != (interruptStatus & 0x8UL))
    {
        context->transferStatus = CY_SMIF_CMD_ERROR;
        Cy_SMIF_ClearInterrupt(base, 0x8UL);
    }
    else if (0U != (interruptStatus & 0x10UL))
    {
        context->transferStatus = CY_SMIF_TX_ERROR;
        Cy_SMIF_ClearInterrupt(base, 0x10UL);
    }
    else if (0U != (interruptStatus & 0x20UL))
    {
        context->transferStatus = CY_SMIF_RX_ERROR;
        Cy_SMIF_ClearInterrupt(base, 0x20UL);
    }
    else
    {
    }
}
static inline void Cy_SMIF_PushTxFifo(SMIF_Type *baseaddr, cy_stc_smif_context_t *context)
{
    uint32_t writeBytes;
    uint32_t freeFifoBytes;
    uint32_t buffCounter = context->txBufferCounter;
    uint8_t *buff = (uint8_t*) context->txBufferAddress;
    freeFifoBytes = (8U) - Cy_SMIF_GetTxFifoStatus(baseaddr);
    writeBytes = (freeFifoBytes > buffCounter)? buffCounter: freeFifoBytes;
    while (0U != writeBytes)
    {
        if (writeBytes == (8U))
        {
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR4) = Cy_SMIF_PackBytesArray(&buff[0U], 1);
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR4) = Cy_SMIF_PackBytesArray(&buff[4U], 1);
        }
        else if(writeBytes == (1U))
        {
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR1) = buff[0U];
        }
        else if ((writeBytes == (2U)) || (writeBytes == (3U)))
        {
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR2) = Cy_SMIF_PackBytesArray(&buff[0U], 0);
            writeBytes = (2U);
        }
        else if ((writeBytes == (4U)) || (writeBytes == (5U)))
        {
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR4) = Cy_SMIF_PackBytesArray(&buff[0U], 1);
            writeBytes = (4U);
        }
        else if ((writeBytes == (6U)) || (writeBytes == (7U)))
        {
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR4) = Cy_SMIF_PackBytesArray(&buff[0U], 1);
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR2) = Cy_SMIF_PackBytesArray(&buff[4U], 0);
            writeBytes = (6U);
        }
        else
        {
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR4) = Cy_SMIF_PackBytesArray(&buff[0U], 1);
            (((SMIF_V1_Type *)(baseaddr))->TX_DATA_FIFO_WR4) = Cy_SMIF_PackBytesArray(&buff[4U], 1);
            writeBytes = (8U);
        }
        buff = &buff[writeBytes];
        buffCounter -= writeBytes;
        freeFifoBytes = (8U) - Cy_SMIF_GetTxFifoStatus(baseaddr);
        writeBytes = (freeFifoBytes > buffCounter)? buffCounter: freeFifoBytes;
    }
    context->txBufferAddress = buff;
    context->txBufferCounter = buffCounter;
    if (0u == buffCounter)
    {
        Cy_SMIF_SetInterruptMask(baseaddr, Cy_SMIF_GetInterruptMask(baseaddr) & ~0x1UL);
        context->transferStatus = CY_SMIF_SEND_COMPLETE;
        if (((void *)0) != context->txCompleteCb)
        {
            context->txCompleteCb((uint32_t) CY_SMIF_SEND_COMPLETE);
        }
    }
}
static inline void Cy_SMIF_PopRxFifo(SMIF_Type *baseaddr, cy_stc_smif_context_t *context)
{
    uint32_t readBytes;
    uint32_t loadedFifoBytes;
    uint32_t buffCounter = context->rxBufferCounter;
    uint8_t *buff = (uint8_t*) context->rxBufferAddress;
    loadedFifoBytes = Cy_SMIF_GetRxFifoStatus(baseaddr);
    readBytes = (loadedFifoBytes > buffCounter)? buffCounter: loadedFifoBytes;
    while (0U != readBytes)
    {
        if (readBytes == (8U))
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[0U], 1);
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[4U], 1);
        }
        else if(readBytes == (1U))
        {
            buff[0U] = (uint8_t)(((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD1);
        }
        else if(readBytes == (2U))
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD2), &buff[0U], 0);
        }
        else if(readBytes == (3U))
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD2), &buff[0U], 0);
            buff[2U] = (uint8_t)(((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD1);
        }
        else if(readBytes == (4U))
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[0U], 1);
        }
        else if(readBytes == (5U))
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[0U], 1);
            buff[4U] = (uint8_t)(((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD1);
        }
        else if(readBytes == (6U))
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[0U], 1);
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD2), &buff[4U], 0);
        }
        else if(readBytes == (7U))
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[0U], 1);
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD2), &buff[4U], 0);
            buff[6U] = (uint8_t)(((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD1);
        }
        else
        {
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[0U], 1);
            Cy_SMIF_UnPackByteArray((((SMIF_V1_Type *)(baseaddr))->RX_DATA_FIFO_RD4), &buff[4U], 1);
            readBytes = (8U);
        }
        buff = &buff[readBytes];
        buffCounter -= readBytes;
        loadedFifoBytes = Cy_SMIF_GetRxFifoStatus(baseaddr);
        readBytes = (loadedFifoBytes > buffCounter)? buffCounter: loadedFifoBytes;
    }
    context->rxBufferAddress = buff;
    context->rxBufferCounter = buffCounter;
    if (0UL == buffCounter)
    {
        Cy_SMIF_SetInterruptMask(baseaddr, Cy_SMIF_GetInterruptMask(baseaddr) & ~0x2UL);
        context->transferStatus = CY_SMIF_RX_COMPLETE;
        if (((void *)0) != context->rxCompleteCb)
        {
            context->rxCompleteCb((uint32_t) CY_SMIF_RX_COMPLETE);
        }
    }
    context->rxBufferCounter = buffCounter;
}
static inline uint32_t Cy_SMIF_PackBytesArray(uint8_t const buff[], _Bool fourBytes)
{
    uint32_t result = 0UL;
    result = ((uint32_t)buff[1UL] << 8UL) | (uint32_t)buff[0UL];
    if(fourBytes)
    {
        result |= ((uint32_t)buff[3UL] << 24UL) | ((uint32_t)buff[2UL] << 16UL);
    }
    return result;
}
static inline void Cy_SMIF_UnPackByteArray(uint32_t inValue, uint8_t outBuff[], _Bool fourBytes)
{
    outBuff[0UL] = (uint8_t)(inValue & 0xFFUL);
    outBuff[1UL] = (uint8_t)((inValue >> 8UL ) & 0xFFUL);
    if(fourBytes)
    {
        outBuff[2UL] = (uint8_t)((inValue >> 16UL) & 0xFFUL);
        outBuff[3UL] = (uint8_t)((inValue >> 24UL) & 0xFFUL);
    }
}
static inline cy_en_smif_status_t Cy_SMIF_TimeoutRun(uint32_t *timeoutUnits)
{
    cy_en_smif_status_t status = CY_SMIF_SUCCESS;
    if (*timeoutUnits > 0u)
    {
        Cy_SysLib_DelayUs((1U));
        --(*timeoutUnits);
        status = (0u == (*timeoutUnits))? CY_SMIF_EXCEED_TIMEOUT: CY_SMIF_SUCCESS;
    }
    return status;
}
