{
    uint32_t pdl_event = 0U;
    if (event & CYHAL_PWM_IRQ_TERMINAL_COUNT)
    {
        pdl_event |= (1U);
    }
    if (event & CYHAL_PWM_IRQ_COMPARE)
    {
        pdl_event |= (2U);
    }
    return pdl_event;
}
